statement:
Three tables track a store's members, their visits and what they bought:

- `Members(member_id, name)`: one row per member; `member_id` is unique (names may repeat).
- `Visits(visit_id, member_id, visit_date)`: one row per visit to the store; `visit_id` is unique and `member_id` is always a member listed in `Members`.
- `Purchases(visit_id, charged_amount)`: one row per visit that ended in a purchase; `visit_id` is unique and always names a row of `Visits`. A visit has at most one purchase.

A member's **conversion rate** is `100 * (number of their visits with a purchase) / (number of their visits)`. Each member gets one category:

- `'Diamond'` when the conversion rate is at least 80;
- `'Gold'` when it is at least 50 but below 80;
- `'Silver'` when it is below 50 (including members who visited but never bought);
- `'Bronze'` when the member never visited the store.

Report every member with the columns `member_id`, `name` and `category`. Rows may come in any order.

validator:
function validate(input) {
  const [{ Members = [], Visits = [], Purchases = [] }] = input;
  const members = new Set(), visits = new Set(), bought = new Set();
  for (const [id, name] of Members) {
    if (id === null || name === null) return 'Every member needs an id and a name.';
    if (members.has(id)) return `member_id ${id} appears twice in Members.`;
    members.add(id);
  }
  for (const [visit, member, date] of Visits) {
    if (visit === null || member === null || date === null) return 'Every Visits column is required.';
    if (visits.has(visit)) return `visit_id ${visit} appears twice in Visits.`;
    visits.add(visit);
    if (!members.has(member)) return `Visit ${visit} names unknown member ${member}.`;
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) return `visit_date ${date} is not YYYY-MM-DD.`;
  }
  for (const [visit, amount] of Purchases) {
    if (visit === null || amount === null) return 'Every Purchases column is required.';
    if (bought.has(visit)) return `Visit ${visit} has two purchases.`;
    bought.add(visit);
    if (!visits.has(visit)) return `Purchase names unknown visit ${visit}.`;
  }
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  const pick = list => list[Math.floor(rand() * list.length)];
  const names = ['Alice', 'Bob', 'Winston', 'Hercy', 'Narihan', 'Mia', 'Omar', 'Lena'];
  const memberCount = small ? Math.floor(rand() * 7) : 500;
  const visitCount = memberCount === 0 ? 0 : small ? Math.floor(rand() * 9) : 2000;
  const Members = [], Visits = [], Purchases = [];
  let id = 1 + Math.floor(rand() * 3);
  for (let i = 0; i < memberCount; i++) { Members.push([id, pick(names)]); id += 1 + Math.floor(rand() * 2); }
  // Small sets send visits to the first few members only, so some members have none and others several.
  const visitors = small ? Members.slice(0, 1 + Math.floor(rand() * Math.max(1, memberCount))) : Members;
  // Each member gets a buying habit so that conversion rates spread over all categories.
  const habit = new Map(Members.map(([member]) => [member, pick([0, 0.3, 0.5, 0.8, 1])]));
  const visitIds = Array.from({ length: small ? 30 : 4000 }, (_, i) => i + 1);
  for (let i = visitIds.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [visitIds[i], visitIds[j]] = [visitIds[j], visitIds[i]]; }
  for (let i = 0; i < visitCount; i++) {
    const [member] = pick(visitors);
    const date = `2021-${String(1 + Math.floor(rand() * 12)).padStart(2, '0')}-${String(1 + Math.floor(rand() * 28)).padStart(2, '0')}`;
    Visits.push([visitIds[i], member, date]);
    if (rand() < habit.get(member)) Purchases.push([visitIds[i], 1000 * (1 + Math.floor(rand() * 10))]);
  }
  return [{ Members, Visits, Purchases }];
}
